def match_parens(lst):
    """You are given a list of two strings containing only '(' or ')'.
    Return 'Yes' if you can concatenate them in some order to form a balanced parentheses string, otherwise return 'No'."""
    def is_balanced(s):
        balance = 0
        for ch in s:
            if ch == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    if len(lst) != 2:
        raise ValueError("Input list must contain exactly two strings")
    a, b = lst
    if not isinstance(a, str) or not isinstance(b, str):
        raise TypeError("Both elements of input list must be strings")
    return 'Yes' if is_balanced(a + b) or is_balanced(b + a) else 'No'

